/**
 * Заглавный экран как книга-панорама: плоские слои иллюстрации на отдельных
 * полигонах с прозрачностью.
 *
 * Каждый слой — PNG в размер кадра, поэтому при нулевом сдвиге слои складываются
 * ровно в исходную картинку. Слои стоят на разной глубине и чуть расходятся
 * (параллакс): ближний ствол уезжает сильнее, дальний лес — почти нет. Плюс
 * «дышащий» свет: тёплый/холодный сдвиг и мягкое пятно солнца, ползущее по кадру.
 */

import * as THREE from 'three';

export interface PlateOptions {
  /** Анимация (волны, облака, параллакс). false — статичная картинка. */
  /** Базовый путь к слоям (обычно import.meta.env.BASE_URL + 'title/layers/'). */
  base: string;
  quality: 'high' | 'medium' | 'low';
  /** Вызывается, когда дальний слой доехал и панораму можно показывать. */
  onReady?: () => void;
  /** Двигаться ли слоям: по умолчанию да, для статичного титула — нет. */
  animate?: boolean;
}

interface LayerSpec {
  name: string;
  /** Глубина в метрах сцены: больше — дальше. */
  depth: number;
  /** Скорость прокрутки текстуры, долей в секунду: вода и облака живут этим. */
  scroll?: [number, number];
  /** Множитель повторения текстуры по осям (для бесшовной воды). */
  repeat?: [number, number];
  /** Прозрачность слоя. */
  opacity?: number;
  /** Сила искажения волн (для воды). */
  ripple?: number;
  /** Яркость пены у берега (для воды). */
  foam?: number;
  /** Имя слоя-маски: показывает, где именно видно текстуру (море, облака). */
  mask?: string;
  /** Имя слоя с бесшовной текстурой, которая прокручивается под маской. */
  tile?: string;
}

/**
 * Материал «текстура под маской»: прокручивается только картинка, маска стоит
 * на месте. Иначе вместе с волной уезжала бы и граница моря.
 */
const SCROLL_SHADER = {
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: `
    uniform sampler2D uTile;
    uniform sampler2D uMask;
    uniform vec2 uOffset;
    uniform vec2 uRepeat;
    uniform float uOpacity;
    uniform float uTime;
    uniform float uRipple;
    uniform float uFoam;
    varying vec2 vUv;

    void main() {
      vec2 uv = vUv * uRepeat;
      // две волны разной частоты идут навстречу — поверхность колышется, а не едет
      float swell = sin(uv.x * 6.0 + uTime * 0.9) * 0.5 + sin(uv.y * 4.0 - uTime * 0.7) * 0.5;
      vec2 shifted = uv + uOffset + vec2(swell, swell * 0.6) * uRipple;
      vec3 color = texture2D(uTile, shifted).rgb;
      // вторая выборка со сдвигом подчёркивает блики на гребнях
      vec3 crest = texture2D(uTile, shifted + vec2(0.03, -0.02)).rgb;
      color = mix(color, max(color, crest), 0.35);
      // пена у берега: чем ниже в кадре, тем сильнее, и она пульсирует
      float shore = smoothstep(0.45, 0.02, vUv.y);
      color += shore * uFoam * (0.6 + 0.4 * sin(uTime * 1.7 + vUv.x * 14.0)) * vec3(0.92, 0.96, 1.0);
      float alpha = texture2D(uMask, vUv).a * uOpacity;
      if (alpha < 0.01) discard;
      gl_FragColor = vec4(color, alpha);
    }`,
};

/** Доля кадра, на которую слои расходятся на опорной глубине. */
const PARALLAX = 0.02;
const PARALLAX_REFERENCE = 12;

/** Глубина по имени слоя: чем меньше, тем ближе к зрителю. */
const DEPTHS: Record<string, number> = {
  forest: 26,
  ground: 15,
  lion: 10,
  trunk_right: 7.5,
  trunk_left: 7,
  traveler: 5.5,
  water: 16,
  clouds: 30,
};

/** Если манифеста нет — берём привычный набор. */
const FALLBACK_LAYERS: LayerSpec[] = Object.entries(DEPTHS)
  .map(([name, depth]) => ({ name, depth }));

export class PlateStack {
  private readonly root = new THREE.Group();
  private readonly plates: {
    mesh: THREE.Mesh;
    material: THREE.Material;
    /** Карта для обычных слоёв (у прокручиваемых текстура живёт в шейдере). */
    map?: THREE.Texture;
    /** Смещение прокрутки для слоёв «текстура под маской». */
    offset?: THREE.Vector2;
    depth: number;
    scroll?: [number, number];
    swell?: number;
    baseY?: number;
    shader?: THREE.ShaderMaterial;
  }[] = [];
  private readonly textures: THREE.Texture[] = [];
  /** Солнечное пятно: есть только в анимированном варианте. */
  private sun: THREE.Mesh | null = null;
  private sunTexture: THREE.Texture | null = null;
  private pointer = new THREE.Vector2();
  private drift = 0;
  private base = 0;
  private lastTime = 0;
  /** Двигается ли сцена (для статичного титула выключается). */
  private animated = true;

  constructor(private readonly camera: THREE.PerspectiveCamera, options: PlateOptions) {
    this.root.name = 'titlePlates';

    // мягкое пятно солнца нужно только в анимированном варианте
    this.animated = options.animate !== false;
    if (!this.animated) {
      // статичный титул: ни солнца, ни прокрутки — только сама иллюстрация
      const loader = new THREE.TextureLoader();
      void this.build(loader, options);
      this.base = performance.now();
      return;
    }
    this.sunTexture = PlateStack.sunTexture();
    const sunMaterial = new THREE.MeshBasicMaterial({
      map: this.sunTexture, transparent: true, depthWrite: false, fog: false,
      blending: THREE.AdditiveBlending, opacity: 0.07,
    });
    this.sun = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), sunMaterial);
    this.sun.name = 'plate_sun';
    this.sun.renderOrder = 0;
    this.root.add(this.sun);

    const loader = new THREE.TextureLoader();
    void this.build(loader, options);
    this.base = performance.now();
  }

  /**
   * Слои описывает манифест `manifest.json` рядом с картинками: набор зависит от
   * того, что получилось при нарезке (у сгенерированной сцены, например, нет
   * отдельного слоя земли). Если манифеста нет — берём привычный набор.
   */
  private async build(loader: THREE.TextureLoader, options: PlateOptions): Promise<void> {
    let specs: LayerSpec[] = FALLBACK_LAYERS;
    try {
      const response = await fetch(`${options.base}manifest.json`);
      if (response.ok) {
        const entries: (string | Partial<LayerSpec> & { name: string })[] = await response.json();
        if (Array.isArray(entries) && entries.length) {
          specs = entries.map((entry) => (typeof entry === 'string'
            ? { name: entry, depth: DEPTHS[entry] ?? 12 }
            : { ...entry, depth: entry.depth ?? DEPTHS[entry.name] ?? 12 }));
        }
      }
    } catch {
      // нет манифеста — остаёмся на привычном наборе
    }

    // Порядок отрисовки: сначала дальние слои, потом ближние. Иначе фон,
    // нарисованный последним, закрывает фигуры (это и случилось в первый раз).
    specs = [...specs].sort((a, b) => b.depth - a.depth);

    for (const spec of specs) {
      // Два вида слоёв: обычная картинка и «текстура под маской» (море, облака),
      // где прокручивается только текстура, а маска стоит на месте.
      if (spec.mask && spec.tile) {
        const shader = new THREE.ShaderMaterial({
          ...SCROLL_SHADER,
          transparent: true,
          depthWrite: false,
          uniforms: {
            uTile: { value: loader.load(`${options.base}${spec.tile}.webp`, (texture) => {
              texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
              texture.colorSpace = THREE.SRGBColorSpace;
            }) },
            uMask: { value: loader.load(`${options.base}${spec.mask}.webp`) },
            uOffset: { value: new THREE.Vector2(0, 0) },
            uRepeat: { value: new THREE.Vector2(...(spec.repeat ?? [1, 1])) },
            uOpacity: { value: spec.opacity ?? 1 },
            uTime: { value: 0 },
            uRipple: { value: spec.ripple ?? 0.01 },
            uFoam: { value: spec.foam ?? 0 },
          },
        });
        const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), shader);
        mesh.name = `plate_${spec.name}`;
        mesh.renderOrder = specs.indexOf(spec);
        this.root.add(mesh);
        this.plates.push({
          mesh, material: shader, depth: spec.depth, scroll: spec.scroll,
          offset: shader.uniforms.uOffset!.value as THREE.Vector2,
          swell: spec.name.startsWith('water') ? 0.05 : undefined,
          shader,
        });
        this.textures.push(
          shader.uniforms.uTile!.value as THREE.Texture,
          shader.uniforms.uMask!.value as THREE.Texture,
        );
        continue;
      }

      const material = new THREE.MeshBasicMaterial({
        transparent: true, depthWrite: false, fog: false, toneMapped: false,
      });
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), material);
      mesh.name = `plate_${spec.name}`;
      mesh.renderOrder = specs.indexOf(spec);
      this.root.add(mesh);
      const plate = {
        mesh, material, depth: spec.depth, scroll: spec.scroll,
        swell: spec.name.startsWith('water') ? 0.05 : undefined,
      } as { mesh: THREE.Mesh; material: THREE.Material; depth: number; map?: THREE.Texture;
              scroll?: [number, number]; swell?: number };
      this.plates.push(plate);

      // Слоёв может быть меньше, чем в манифесте: отсутствующий файл просто
      // не создаёт плоскость (и не оставляет белый прямоугольник).
      const texture = loader.load(`${options.base}${spec.name}.webp`, () => {
        if (spec.name === 'forest' || specs.length === 1) options.onReady?.();
      }, undefined, () => {
        this.root.remove(mesh);
        const index = this.plates.findIndex((item) => item.mesh === mesh);
        if (index >= 0) this.plates.splice(index, 1);
        material.dispose();
      });
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.generateMipmaps = false;
      if (spec.repeat) {
        texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(spec.repeat[0], spec.repeat[1]);
      }
      if (spec.scroll) {
        // прокрутка требует повторения текстуры, иначе край уедет и обнажит фон
        texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      }
      material.map = texture;
      if (spec.opacity !== undefined) material.opacity = spec.opacity;
      plate.map = texture;
      this.textures.push(texture);
    }

    this.layout();
  }

  /** Мягкое радиальное пятно — «солнце» для живописного света. */
  private static sunTexture(): THREE.Texture {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 256;
    const context = canvas.getContext('2d')!;
    const gradient = context.createRadialGradient(128, 128, 8, 128, 128, 128);
    gradient.addColorStop(0, 'rgba(255, 232, 178, 0.95)');
    gradient.addColorStop(0.45, 'rgba(255, 206, 132, 0.35)');
    gradient.addColorStop(1, 'rgba(255, 190, 110, 0)');
    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 256);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return texture;
  }

  get object3d(): THREE.Object3D {
    return this.root;
  }

  /** Параллакс от курсора: на телефоне просто не вызывается. */
  setPointer(x: number, y: number): void {
    this.pointer.set(x, y);
  }

  /** Переставить слои под текущий размер кадра. */
  layout(): void {
    const halfHeight = (depth: number): number =>
      Math.tan((this.camera.fov / 2) * (Math.PI / 180)) * depth;
    const direction = new THREE.Vector3();
    const right = new THREE.Vector3();
    const up = new THREE.Vector3();
    this.camera.getWorldDirection(direction);
    right.crossVectors(direction, this.camera.up).normalize();
    up.crossVectors(right, direction).normalize();

    for (const plate of this.plates) {
      const { mesh, depth } = plate;
      const halfH = halfHeight(depth);
      const halfW = halfH * this.camera.aspect;
      const reach = PARALLAX * (PARALLAX_REFERENCE / depth);
      // запас 2*reach + 2 %: при сдвиге края кадра не оголяются
      const margin = (this.animated ? 1 + reach * 2 : 1) + 0.02;

      // ВАЖНО про пропорции: картинку вписываем с сохранением её собственных
      // пропорций (как object-fit: cover), иначе кадр растягивается под формат окна.
      const source = plate.map ?? (plate.shader?.uniforms.uTile?.value as THREE.Texture | undefined);
      const image = source?.image as { width?: number; height?: number } | undefined;
      const frameWidth = 2 * halfW * margin;
      const frameHeight = 2 * halfH * margin;
      let width = frameWidth;
      let height = frameHeight;
      if (image?.width && image?.height) {
        // Вписываем картинку ЦЕЛИКОМ (как object-fit: contain): пропорции сохраняются,
        // а поля вокруг закрывает чёрный фон сцены. Растягивать или зумить нельзя —
        // при повороте телефона кадр превращался в случайный кусок картинки.
        const scale = Math.min(frameWidth / image.width, frameHeight / image.height);
        width = image.width * scale;
        height = image.height * scale;
      }
      const plane = mesh.geometry as THREE.PlaneGeometry;
      if (Math.abs(plane.parameters.width - width) > 0.001 || Math.abs(plane.parameters.height - height) > 0.001) {
        mesh.geometry.dispose();
        mesh.geometry = new THREE.PlaneGeometry(width, height);
      }
      mesh.position.copy(this.camera.position).addScaledVector(direction, depth);
      mesh.quaternion.copy(this.camera.quaternion);
      plate.baseY = mesh.position.y;
    }


    if (!this.sun) return;   // статичный титул: пятна солнца нет
    const sunDepth = 9;
    const halfH = halfHeight(sunDepth);
    this.sun.geometry.dispose();
    this.sun.geometry = new THREE.PlaneGeometry(halfH * this.camera.aspect * 3.2, halfH * 2.6);
    this.sun.position.copy(this.camera.position);
    this.sun.quaternion.copy(this.camera.quaternion);
    this.sun.translateZ(-sunDepth);
  }

  /** Покадрово: параллакс, прокрутка воды и облаков, «дыхание» света. */
  update(time: number): void {
    if (!this.animated) return;   // статичный титул: ничего не двигается
    const delta = this.lastTime ? Math.min(0.05, time - this.lastTime) : 0;
    this.lastTime = time;
    for (const plate of this.plates) {
      if (plate.shader) plate.shader.uniforms.uTime!.value = time;
      if (plate.offset && plate.scroll) {
        // море и облака: едет текстура, маска стоит на месте
        plate.offset.x = (plate.offset.x + plate.scroll[0] * delta) % 1;
        plate.offset.y = (plate.offset.y + plate.scroll[1] * delta) % 1;
        continue;
      }
      const texture = plate.map;
      if (!texture || !plate.scroll) continue;
      texture.offset.x = (texture.offset.x + plate.scroll[0] * delta) % 1;
      texture.offset.y = (texture.offset.y + plate.scroll[1] * delta) % 1;
      // море чуть «дышит» по вертикали — волна идёт на зрителя
      if (plate.swell && plate.baseY !== undefined) {
        plate.mesh.position.y = plate.baseY + Math.sin(time * 0.6 + plate.depth) * plate.swell;
      }
    }

    // медленный дрейф камеры + реакция на курсор
    const driftX = Math.sin(time * 0.11) * 0.55 + Math.sin(time * 0.37) * 0.2;
    const driftY = Math.cos(time * 0.09) * 0.5 + Math.sin(time * 0.23) * 0.18;
    const pointerX = this.pointer.x * 0.7;
    const pointerY = this.pointer.y * 0.5;
    this.drift = Math.sin(time * 0.13) * 0.5 + 0.5;

    const direction = new THREE.Vector3();
    const right = new THREE.Vector3();
    const up = new THREE.Vector3();
    this.camera.getWorldDirection(direction);
    right.crossVectors(direction, this.camera.up).normalize();
    up.crossVectors(right, direction).normalize();
    const halfHeight = (depth: number): number =>
      Math.tan((this.camera.fov / 2) * (Math.PI / 180)) * depth;

    for (const { mesh, material, depth } of this.plates) {
      const reach = PARALLAX * (PARALLAX_REFERENCE / depth);
      const ndcX = (driftX + pointerX) * reach;
      const ndcY = (driftY + pointerY) * reach * 0.7;
      const halfH = halfHeight(depth);
      mesh.position.copy(this.camera.position).addScaledVector(direction, depth)
        .addScaledVector(right, ndcX * halfH * this.camera.aspect)
        .addScaledVector(up, ndcY * halfH);
      // свет «дышит»: тёплый ↔ холодный, дальние слои сильнее
      const warm = Math.sin(time * 0.13) * 0.5 + 0.5;
      const shift = (depth > 20 ? 0.10 : 0.06) * (warm - 0.5) * 2;
      const basic = material as THREE.MeshBasicMaterial;
      if (basic.color) basic.color.setRGB(1 + shift, 1 + shift * 0.35, 1 - shift * 0.8);
    }


    if (this.sun) {
      const sunMaterial = this.sun.material as THREE.MeshBasicMaterial;
      sunMaterial.opacity = 0.06 + Math.sin(time * 0.17) * 0.03;
      this.sun.position.x += Math.sin(time * 0.05) * 0.02;
    }
  }

  /** Есть ли в наборе слоёв море: нужно, чтобы включить брызги. */
  get hasSea(): boolean {
    return this.plates.some((plate) => plate.mesh.name === 'plate_water');
  }

  dispose(): void {
    for (const { mesh } of this.plates) mesh.geometry.dispose();
    for (const { material } of this.plates) material.dispose();
    for (const texture of this.textures) texture.dispose();
    this.sun?.geometry.dispose();
    if (this.sun) (this.sun.material as THREE.Material).dispose();
    this.sunTexture?.dispose();
    this.root.removeFromParent();
  }
}
